            <text x='20' y='74' style='fill: var(--kerykeion-chart-color-paper-0); font-size: 10px'>1968-10-12 21:16 [-04:00]</text>
            <text x='20' y='86' style='fill: var(--kerykeion-chart-color-paper-0); font-size: 10px'>Latitude: 33°52'11' South</text>
